import{_ as n,c as a,o as r,ag as o}from"./chunks/framework.CQuhCYrb.js";const m=JSON.parse('{"title":"Guide to Drone Deployment and Coordination in Disaster Relief","description":"","frontmatter":{"title":"Guide to Drone Deployment and Coordination in Disaster Relief"},"headers":[],"relativePath":"general/guide-to-drone-deployment-and-coordination-in-disaster-relief.md","filePath":"general/guide-to-drone-deployment-and-coordination-in-disaster-relief.md","lastUpdated":null}'),i={name:"general/guide-to-drone-deployment-and-coordination-in-disaster-relief.md"};function t(s,e,l,c,d,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="guide-to-drone-deployment-and-coordination-in-disaster-relief" tabindex="-1">Guide to Drone Deployment and Coordination in Disaster Relief <a class="header-anchor" href="#guide-to-drone-deployment-and-coordination-in-disaster-relief" aria-label="Permalink to &quot;Guide to Drone Deployment and Coordination in Disaster Relief&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>In the aftermath of Hurricane Helene in 2024, Western North Carolina witnessed significant involvement from volunteers utilizing Unmanned Aerial Systems (UAS), commonly known as drones, in disaster relief operations. This experience highlighted several critical lessons and best practices for hobbyists and volunteers aiming to assist in future disaster scenarios.</p><p>Further discussion on this topic and questions a volunteer might ask are on the <a href="https://forum.irregularchat.com/t/what-are-the-best-practices-for-operational-safety-in-disaster-areas/357" target="_blank" rel="noreferrer">forum</a></p><h3 id="key-lessons-learned" tabindex="-1">Key Lessons Learned <a class="header-anchor" href="#key-lessons-learned" aria-label="Permalink to &quot;Key Lessons Learned&quot;">​</a></h3><h3 id="airspace-coordination" tabindex="-1">Airspace Coordination <a class="header-anchor" href="#airspace-coordination" aria-label="Permalink to &quot;Airspace Coordination&quot;">​</a></h3><ul><li><p><strong>Importance of Coordination</strong>: Effective airspace management prevents conflicts between manned and unmanned aircraft. During the relief efforts, the absence of centralized coordination led to multiple mid-air close calls, underscoring the need for structured airspace management.)(<a href="https://www.dji.com" target="_blank" rel="noreferrer">https://www.dji.com</a>).</p></li><li><p><strong>Communication Tools</strong>: Satellite-based internet services like Starlink provided crucial connectivity in areas where traditional communication networks were down.)(<a href="https://www.arrl.org" target="_blank" rel="noreferrer">https://www.arrl.org</a>).</p></li></ul><h3 id="volunteer-management" tabindex="-1">Volunteer Management <a class="header-anchor" href="#volunteer-management" aria-label="Permalink to &quot;Volunteer Management&quot;">​</a></h3><ul><li><p><strong>Decentralized Efforts</strong>: The lack of centralized leadership led to localized efforts at airports and community centers, which proved the most effective.</p></li><li><p><strong>Role of Agencies</strong>: The Federal Emergency Management Agency (FEMA) faced challenges due to inadequate operational infrastructure, highlighting the importance of community-driven initiatives in the initial 24-48 hours post-disaster.</p></li></ul><h3 id="training-and-standard-operating-procedures-sops" tabindex="-1">Training and Standard Operating Procedures (SOPs) <a class="header-anchor" href="#training-and-standard-operating-procedures-sops" aria-label="Permalink to &quot;Training and Standard Operating Procedures (SOPs)&quot;">​</a></h3><ul><li><p><strong>Regulatory Compliance</strong>: Operators should have a clear understanding of relevant regulations:</p><ul><li>Civilian Operators: Federal Aviation Administration (FAA) Part 107 Certification. See <a href="https://www.faa.gov/uas/commercial_operators/become_a_drone_pilot" target="_blank" rel="noreferrer">Non Active</a>.)(/non-active)</li></ul></li><li><p><strong>Development of SOPs</strong>: Establishing SOPs is vital for rapid and organized deployment during disaster scenarios.</p></li></ul><h3 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h3><ul><li><p><strong>Open Communication Lines</strong>: Establishing shared platforms for drone operators to coordinate airspace usage is essential.</p></li><li><p><strong>Use of Repeaters</strong>: Deploying repeaters and frequency management systems can enhance emergency communication capabilities.</p></li></ul><h3 id="policy-gaps" tabindex="-1">Policy Gaps <a class="header-anchor" href="#policy-gaps" aria-label="Permalink to &quot;Policy Gaps&quot;">​</a></h3><ul><li><p><strong>Tracking Systems</strong>: The absence of a centralized database or network for tracking civilian drone operations during emergencies poses challenges.</p></li><li><p><strong>Integration of Command and Control (C2)</strong>: Agencies like FEMA must incorporate C2 infrastructure into their disaster response frameworks to improve coordination.</p></li></ul><h3 id="recommendations-for-future-efforts" tabindex="-1">Recommendations for Future Efforts <a class="header-anchor" href="#recommendations-for-future-efforts" aria-label="Permalink to &quot;Recommendations for Future Efforts&quot;">​</a></h3><p>Policy Development:</p><ul><li><p><strong>Establish Clear Guidelines</strong>: Agencies should develop clear policies for integrating volunteer UAS operations into official disaster response efforts.</p></li><li><p><strong>Centralized Airspace Management</strong>: Creating a centralized platform for airspace management during disasters can prevent conflicts and enhance safety.</p></li></ul><p>Training and Preparation:</p><ul><li><p><strong>Community Workshops</strong>: Organizing regular workshops can train hobbyists and volunteers on Search and Rescue (SAR) drone operations.</p></li><li><p><strong>Simulation Drills</strong>: Conducting drills to simulate disaster scenarios can prepare volunteers for real-world situations.</p></li></ul><p>Technology Enhancements:</p><ul><li><p><strong>Affordable Communication Tools</strong>: Expanding access to affordable communication tools like HAM radios and satellite internet services for emergency use is crucial.</p></li><li><p><strong>FAA Policy Advocacy</strong>: Advocating for FAA policies that allow area-wide drone operation unlocks during disasters, with appropriate safeguards, can facilitate rapid response.</p></li></ul><p>Community Organization:</p><ul><li><p><strong>Formation of Volunteer Groups</strong>: Encouraging the creation of local volunteer groups can streamline response efforts and improve coordination.</p></li><li><p><strong>Partnerships with Emergency Services</strong>: Establishing partnerships with local emergency management and fire departments can facilitate resource sharing and enhance response capabilities.</p></li></ul><h3 id="open-source-communication-tools-for-disaster-scenarios" tabindex="-1">Open-Source Communication Tools for Disaster Scenarios <a class="header-anchor" href="#open-source-communication-tools-for-disaster-scenarios" aria-label="Permalink to &quot;Open-Source Communication Tools for Disaster Scenarios&quot;">​</a></h3><p>In disaster situations where traditional communication networks are compromised, open-source mesh networking tools can provide resilient alternatives:</p><ul><li><strong><a href="https://meshtastic.org/" target="_blank" rel="noreferrer">Meshtastic</a></strong>: <ul><li>Overview: Meshtastic is an open-source project that utilizes inexpensive LoRa radios to create a mesh network, enabling off-grid, long-range communication without relying on cellular or internet infrastructure.)**:</li><li>Overview: Briar is an open-source communication tool designed for secure and resilient peer-to-peer messaging without centralized servers, operating over Bluetooth, Wi-Fi, or the internet via Tor.)**:</li><li>Overview: OpenDroneMap is an open-source project for processing aerial imagery captured by drones into maps, 3D models, and other geospatial data formats.)(<a href="https://gotenna.com" target="_blank" rel="noreferrer">https://gotenna.com</a>).</li><li>Applications: Can supplement other mesh networking solutions for small-scale, localized disaster response.</li></ul></li></ul><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3>',28)])])}const g=n(i,[["render",t]]);export{m as __pageData,g as default};
